[planner] {
  "plan": {
    "objective": "Produce a benchmark-ready long-horizon experiment plan",
    "coverage": ["tool use", "evidence collection", "delegation", "synthesis", "risk tracking"],
    "phases": [
      {
        "phase": "Clarify & Scope",
        "steps": ["Define success criteria for 'benchmark-ready'", "Specify time horizon (e.g., 6–24 months)", "Identify evaluation metrics (e.g., reproducibility, coverage, auditability)"]
      },
      {
        "phase": "Tool Use Strategy",
        "steps": ["Select and validate tools per function: local_lookup for evidence, plan_outline for scaffolding, plus future tools for execution/monitoring", "Define tool invocation protocols (input validation, error fallbacks, version pinning)"]
      },
      {
        "phase": "Evidence Collection",
        "steps": ["Systematically retrieve domain-relevant baselines via local_lookup", "Log provenance (timestamp, query, artifact ID)", "Tag evidence by type (empirical, procedural, normative)"]
      },
      {
        "phase": "Delegation Framework",
        "steps": ["Assign subtasks using matriarchal_elephant topology", "Enforce handoff_policy = 'summary_plus_artifacts'", "Require shared_workspace_policy = 'artifacts_first' for all delegated outputs"]
      },
      {
        "phase": "Synthesis Protocol",
        "steps": ["Aggregate outputs into unified timeline + dependency graph", "Cross-validate claims against collected evidence", "Generate human- and machine-readable summaries (JSON + Markdown)"]
      },
      {
        "phase": "Risk Tracking",
        "steps": ["Log risks per category: tool failure, evidence decay, delegation drift, synthesis bias, temporal misalignment", "Assign severity, owner, mitigation window, and trigger conditions", "Integrate with automated alerting on staleness or inconsistency"]
      }
    ],
    "output_format": {
      "structure": ["executive_summary", "phase_schedule", "tool_inventory", "evidence_log_schema", "delegation_map", "synthesis_template", "risk_register"],
      "benchmark_compliance": ["GAIA-RQ1 alignment", "replicability checklist", "traceability IDs per component"]
    }
  }
}

[reviewer] {
  "plan": {
    "horizon": "long",
    "benchmark_readiness": true,
    "components": {
      "tool_use": {
        "strategy": "Tool-augmented iterative refinement",
        "tools": ["plan_outline", "local_lookup"],
        "validation": "Each tool call must return structured, deterministic output; unused tools are logged and justified."
      },
      "evidence_collection": {
        "sources": ["local_lookup (domain-specific experimental patterns)", "plan_outline (scaffolded step decomposition)"],
        "format": "Structured JSON with provenance (tool name, query, timestamp)",
        "coverage": "Evidence must span all five core dimensions: tool use, evidence collection, delegation, synthesis, risk tracking"
      },
      "delegation": {
        "policy": "summary_plus_artifacts",
        "topology": "matriarchal_elephant",
        "handoff_criteria": "Subtask completion + artifact generation (no verbal-only handoffs)",
        "depth_limit": 2
      },
      "synthesis": {
        "method": "Artifact-first aggregation",
        "output_format": "Markdown with embedded JSON metadata blocks for traceability",
        "validation_check": "All delegated subtasks must be represented in final synthesis with evidence links"
      },
      "risk_tracking": {
        "categories": ["tool failure", "evidence gap", "delegation drift", "synthesis inconsistency", "temporal horizon slippage"],
        "log_frequency": "per-step",
        "mitigation": ["fallback tool invocation", "evidence re-query", "handoff audit", "cross-component consistency check"]
      }
    }
  }
}
